package com.pianoquest.app.data

data class GlossaryEntry(val term: String, val category: String, val definition: String, val visual: Visual? = null, val play: String? = null)

/** The Theory Encyclopedia: every core concept, searchable. */
object Glossary {
    private fun e(term: String, cat: String, def: String, visual: Visual? = null, play: String? = null) = GlossaryEntry(term, cat, def, visual, play)

    val entries: List<GlossaryEntry> by lazy { (pitch() + rhythm() + scales() + chords() + harmony() + form() + expression() + piano() + styles()).sortedBy { it.term.lowercase() } }

    val categories: List<String> get() = entries.map { it.category }.distinct().sorted()

